'use client';

import React from 'react';
import {
  AreaChart,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  ReferenceLine,
} from 'recharts';
import { formatPrice } from '@/lib/scoring';

interface TradingViewChartProps {
  data: Array<{
    time: string;
    price: number;
    volume?: number;
  }>;
  title?: string;
  height?: number;
  color?: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: Array<{ value: number }>;
  label?: string;
}

// Custom tooltip
const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length) {
    return (
      <div className="bg-card border border-border rounded-lg p-3 shadow-xl">
        <p className="text-xs text-muted-foreground mb-1">{label}</p>
        <p className="text-sm font-bold text-foreground">
          {formatPrice(payload[0].value)}
        </p>
      </div>
    );
  }
  return null;
};

export const TradingViewChart: React.FC<TradingViewChartProps> = ({
  data,
  title = 'نمودار قیمت',
  height = 300,
  color = '#22c55e',
}) => {
  const latestPrice = data.length > 0 ? data[data.length - 1].price : 0;
  const previousPrice = data.length > 1 ? data[data.length - 2].price : latestPrice;
  const priceChange = latestPrice - previousPrice;
  const priceChangePercent = ((priceChange / previousPrice) * 100);
  const isPositive = priceChange >= 0;

  return (
    <div className="w-full bg-card rounded-2xl border border-border overflow-hidden">
      {/* Header */}
      <div className="px-6 py-4 border-b border-border flex items-center justify-between">
        <div>
          <h3 className="text-sm font-semibold text-foreground">{title}</h3>
          <div className="flex items-center gap-2 mt-1">
            <span className="text-xl font-bold text-foreground">
              {formatPrice(latestPrice)}
            </span>
            <span 
              className={`text-xs font-bold px-2 py-1 rounded ${
                isPositive ? 'bg-chart-4/20 text-chart-4' : 'bg-destructive/20 text-destructive'
              }`}
            >
              {isPositive ? '+' : ''}{priceChangePercent.toFixed(2)}%
            </span>
          </div>
        </div>
        
        {/* Timeframe buttons */}
        <div className="flex gap-1">
          {['1H', '4H', '1D', '1W', '1M'].map((tf) => (
            <button
              key={tf}
              className={`px-3 py-1 text-xs font-medium rounded transition-colors duration-300 ease-magic ${
                tf === '1D' 
                  ? 'bg-primary text-primary-foreground' 
                  : 'text-muted-foreground hover:bg-accent/50'
              }`}
            >
              {tf}
            </button>
          ))}
        </div>
      </div>

      {/* Chart */}
      <div className="p-4">
        <ResponsiveContainer width="100%" height={height}>
          <AreaChart data={data}>
            <defs>
              <linearGradient id={`colorPrice-${title}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={color} stopOpacity={0.3} />
                <stop offset="95%" stopColor={color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid 
              strokeDasharray="3 3" 
              stroke="var(--border)" 
              vertical={false}
            />
            <XAxis 
              dataKey="time" 
              stroke="var(--muted-foreground)" 
              fontSize={10}
              tickLine={false}
              axisLine={false}
              tick={{ fill: 'var(--muted-foreground)' }}
            />
            <YAxis 
              stroke="var(--muted-foreground)" 
              fontSize={10}
              tickLine={false}
              axisLine={false}
              tick={{ fill: 'var(--muted-foreground)' }}
              tickFormatter={(value) => formatPrice(value).slice(0, 8)}
              orientation="right"
            />
            <Tooltip content={<CustomTooltip />} />
            
            {/* Reference line for previous close */}
            {data.length > 0 && (
              <ReferenceLine 
                y={data[0].price} 
                stroke="var(--border)" 
                strokeDasharray="3 3"
              />
            )}
            
            <Area 
              type="monotone" 
              dataKey="price" 
              stroke={color} 
              strokeWidth={2}
              fillOpacity={1} 
              fill={`url(#colorPrice-${title})`}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default TradingViewChart;
