'use client';

import { useState, useMemo } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ProgressDynamic } from '@/components/ui/progress-dynamic';
import {
  TrendingUp,
  TrendingDown,
  Activity,
  DollarSign,
  Clock,
  AlertCircle,
  CheckCircle,
} from 'lucide-react';
import { SymbolScore, getScoreColor, formatNumber, formatPrice } from '@/lib/scoring';
import { SymbolData } from '@/lib/scoring';
import { TradingViewChart } from './TradingViewChart';
import { TechnicalOscillator } from './TechnicalOscillator';

// Generate mock price history
function generatePriceHistory(basePrice: number, days: number = 30) {
  const data: Array<{ time: string; price: number }> = [];
  let price = basePrice;
  for (let i = days - 1; i >= 0; i--) {
    const change = (Math.random() - 0.5) * basePrice * 0.05;
    price += change;
    const date = new Date();
    date.setDate(date.getDate() - i);
    data.push({
      time: date.toLocaleDateString('fa-IR', { month: 'short', day: 'numeric' }),
      price: Math.max(price, basePrice * 0.7),
    });
  }
  return data;
}

interface SymbolDetailProps {
  symbol: SymbolData | null;
  score: SymbolScore | null;
  open: boolean;
  onClose: () => void;
}

export function SymbolDetail({ symbol, score, open, onClose }: SymbolDetailProps) {
  const [activeTab, setActiveTab] = useState('overview');
  
  const priceHistory = useMemo(() => {
    if (symbol) {
      return generatePriceHistory(symbol.price);
    }
    return [];
  }, [symbol]);

  if (!symbol || !score) return null;

  const getRecommendation = (score: number) => {
    if (score >= 7.5) return { text: 'خرید قوی', color: 'text-emerald-500', icon: CheckCircle };
    if (score >= 5) return { text: 'خرید متوسط', color: 'text-amber-500', icon: Activity };
    if (score >= 3) return { text: 'احتیاط', color: 'text-orange-500', icon: AlertCircle };
    return { text: 'فروش', color: 'text-red-500', icon: TrendingDown };
  };

  const recommendation = getRecommendation(score.totalScore);
  const RecommendationIcon = recommendation.icon;

  // Oscillator colors for dimensions
  const oscillatorColors = [
    '#34d399',
    '#2dd4bf',
    '#a78bfa',
    '#f87171',
    '#fbbf24',
    '#60a5fa',
  ];

  return (
    <Dialog open={open} onOpenChange={(v) => !v && onClose()}>
      <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-2xl font-bold flex items-center gap-3">
            <span className="text-3xl">{symbol.symbol}</span>
            <Badge variant="secondary" className="text-sm">{symbol.market}</Badge>
            <Badge variant="outline" className="text-sm">{symbol.sector}</Badge>
          </DialogTitle>
          <DialogDescription className="text-base text-muted-foreground">
            {symbol.name}
          </DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="overview" value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="w-full sm:w-auto mb-6 bg-card border border-border">
            <TabsTrigger value="overview" className="text-sm">نمای کلی</TabsTrigger>
            <TabsTrigger value="chart" className="text-sm">نمودار</TabsTrigger>
            <TabsTrigger value="oscillators" className="text-sm">اسیلاتورها</TabsTrigger>
            <TabsTrigger value="financials" className="text-sm">اطلاعات مالی</TabsTrigger>
          </TabsList>

          <TabsContent value="overview" className="space-y-6">
            {/* Price and Key Info */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
              {/* Main Price Card */}
              <div className="lg:col-span-2 bg-gradient-to-br from-card to-background rounded-2xl p-6 border border-border">
                <div className="flex items-center justify-between mb-6">
                  <div>
                    <div className="text-xs text-muted-foreground mb-2">قیمت فعلی</div>
                    <div className="text-4xl font-black text-foreground flex items-center gap-3">
                      {formatPrice(symbol.price)}
                      <span className={`text-sm font-semibold flex items-center gap-1 ${
                        symbol.changePercent >= 0 ? 'text-primary' : 'text-destructive'
                      }`}>
                        {symbol.changePercent >= 0 ? <TrendingUp className="size-4" /> : <TrendingDown className="size-4" />}
                        {symbol.changePercent >= 0 ? '+' : ''}{symbol.changePercent.toFixed(2)}%
                      </span>
                    </div>
                  </div>
                  <div className="text-center p-4 bg-white/5 rounded-xl border border-white/10">
                    <RecommendationIcon className={`size-10 mx-auto mb-2 ${recommendation.color}`} />
                    <div className={`text-sm font-bold ${recommendation.color}`}>{recommendation.text}</div>
                  </div>
                </div>

                {/* Quick Stats */}
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                  <div className="p-3 bg-white/5 rounded-lg border border-white/10">
                    <div className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                      <DollarSign className="size-3" /> ارزش بازار
                    </div>
                    <div className="text-lg font-bold">{formatPrice(symbol.marketCap)}</div>
                  </div>
                  <div className="p-3 bg-white/5 rounded-lg border border-white/10">
                    <div className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                      <Activity className="size-3" /> حجم معاملات
                    </div>
                    <div className="text-lg font-bold">{formatNumber(symbol.volume)}</div>
                  </div>
                  <div className="p-3 bg-white/5 rounded-lg border border-white/10">
                    <div className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                      <Clock className="size-3" /> بالاتر روز
                    </div>
                    <div className="text-lg font-bold">{formatPrice(symbol.price * 1.02)}</div>
                  </div>
                  <div className="p-3 bg-white/5 rounded-lg border border-white/10">
                    <div className="text-xs text-muted-foreground mb-1 flex items-center gap-1">
                      <Clock className="size-3" /> پایین‌تر روز
                    </div>
                    <div className="text-lg font-bold">{formatPrice(symbol.price * 0.98)}</div>
                  </div>
                </div>
              </div>

              {/* Score Summary */}
              <div className="bg-gradient-to-br from-card to-background rounded-2xl p-6 border border-border">
                <div className="text-center">
                  <div className="text-xs text-muted-foreground mb-2">امتیاز کلی</div>
                  <div className={`text-6xl font-black mb-2 ${getScoreColor(score.totalScore)}`}>
                    {score.totalScore.toFixed(1)}
                  </div>
                  <div className="text-xs text-muted-foreground">از 10</div>
                  <ProgressDynamic 
                    value={score.totalScore * 10} 
                    className="h-3 mt-4"
                  />
                </div>

                <div className="mt-6 space-y-3">
                  {score.dimensions.slice(0, 3).map((dim) => (
                    <div key={dim.key} className="flex items-center justify-between">
                      <span className="text-xs text-muted-foreground">{dim.name}</span>
                      <span className={`text-sm font-semibold ${getScoreColor(dim.score)}`}>
                        {dim.score.toFixed(1)}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Mini Price Chart */}
            <TradingViewChart 
              data={priceHistory} 
              title="روند قیمت 30 روزه"
              height={250}
              color="#34d399"
            />
          </TabsContent>

          <TabsContent value="chart" className="space-y-4">
            <TradingViewChart 
              data={priceHistory} 
              title={`نمودار ${symbol.symbol}`}
              height={450}
              color="#34d399"
            />
          </TabsContent>

          <TabsContent value="oscillators" className="space-y-6">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* Technical Oscillators for each dimension */}
              <div className="bg-card rounded-2xl p-6 border border-border">
                <h3 className="text-sm font-semibold mb-6 text-foreground">
                  اسیلاتورهای شاخص ۶ بعدی
                </h3>
                <div className="space-y-6">
                  {score.dimensions.map((dim, i) => (
                    <TechnicalOscillator
                      key={dim.key}
                      value={dim.score * 10}
                      label={dim.name}
                      color={oscillatorColors[i % oscillatorColors.length]}
                    />
                  ))}
                </div>
              </div>

              {/* Summary Card */}
              <div className="space-y-6">
                <div className="bg-gradient-to-br from-primary/10 to-secondary/10 rounded-2xl p-6 border border-primary/30">
                  <h4 className="text-sm font-semibold text-primary mb-4">خلاصه سیگنال‌ها</h4>
                  <div className="space-y-3">
                    {score.dimensions.map((dim) => {
                      const isPositive = dim.score >= 5;
                      return (
                        <div key={dim.key} className="flex items-center justify-between">
                          <span className="text-xs text-muted-foreground">{dim.name}</span>
                          <Badge 
                            className={`text-xs ${
                              isPositive 
                                ? 'bg-primary/20 text-primary' 
                                : 'bg-destructive/20 text-destructive'
                            }`}
                          >
                            {isPositive ? 'مثبت' : 'منفی'}
                          </Badge>
                        </div>
                      );
                    })}
                  </div>
                </div>

                <div className="bg-card rounded-2xl p-6 border border-border">
                  <h4 className="text-sm font-semibold text-foreground mb-4">
                    توضیح نقاط اسیلاتور
                  </h4>
                  <div className="space-y-2 text-xs text-muted-foreground">
                    <p><span className="text-primary font-bold">0-25:</span> منطقه فروش شدید</p>
                    <p><span className="text-chart-4 font-bold">25-75:</span> منطقه خنثی / تجمع</p>
                    <p><span className="text-primary font-bold">75-100:</span> منطقه خرید شدید</p>
                  </div>
                </div>
              </div>
            </div>
          </TabsContent>

          <TabsContent value="financials" className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
              {[
                { label: 'P/E Ratio', value: '12.5' },
                { label: 'P/B Ratio', value: '1.8' },
                { label: 'Dividend Yield', value: '3.2%' },
                { label: 'ROE', value: '18.5%' },
                { label: 'Debt/Equity', value: '0.45' },
                { label: 'Market Cap', value: formatPrice(symbol.marketCap) },
              ].map((item, i) => (
                <div key={i} className="p-4 bg-card rounded-xl border border-border">
                  <div className="text-xs text-muted-foreground">{item.label}</div>
                  <div className="text-lg font-bold mt-1">{item.value}</div>
                </div>
              ))}
            </div>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

// Default export for lazy loading
export default SymbolDetail;
