'use client';

import React from 'react';

interface TechnicalOscillatorProps {
  value: number; // 0-100
  label: string;
  color: string;
  showValue?: boolean;
}

export const TechnicalOscillator: React.FC<TechnicalOscillatorProps> = ({
  value,
  label,
  color,
  showValue = true,
}) => {
  // Clamp value between 0-100
  const clampedValue = Math.max(0, Math.min(100, value));

  return (
    <div className="w-full space-y-2">
      <div className="flex items-center justify-between">
        <span className="text-xs font-medium text-muted-foreground">{label}</span>
        {showValue && (
          <span 
            className="text-xs font-bold"
            style={{ color }}
          >
            {clampedValue.toFixed(0)}
          </span>
        )}
      </div>
      
      {/* Oscillator Track */}
      <div className="relative w-full h-4 bg-gradient-to-r from-destructive via-accent to-chart-4 rounded-full overflow-hidden">
        {/* Zone markers */}
        <div className="absolute left-[20%] top-0 bottom-0 w-px bg-white/30" />
        <div className="absolute left-[80%] top-0 bottom-0 w-px bg-white/30" />
        
        {/* Needle/Pointer */}
        <div 
          className="absolute top-0 bottom-0 transition-all duration-300 ease-magic"
          style={{ 
            left: `calc(${clampedValue}% - 2px)`,
            width: '4px',
            background: color,
            boxShadow: `0 0 10px ${color}`,
            borderRadius: '2px',
          }}
        >
          {/* Triangle indicator on top */}
          <div 
            className="absolute -top-2 left-1/2 -translate-x-1/2 w-0 h-0"
            style={{
              borderLeft: '6px solid transparent',
              borderRight: '6px solid transparent',
              borderBottom: `8px solid ${color}`,
            }}
          />
        </div>
      </div>

      {/* Zone labels */}
      <div className="flex justify-between text-[10px] text-muted-foreground px-1">
        <span>فروش شدید</span>
        <span>خنثی</span>
        <span>خرید شدید</span>
      </div>
    </div>
  );
};

export default TechnicalOscillator;
